/// What a vendor kind is measured in. Standard kinds carry their unit in the
/// metric table; a vendor kind carries it on the row, and needs a number to
/// carry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
#[repr(u8)]
pub enum Unit {
    /// V.
    ///
    /// Reserved: allocated, and not specified yet.
    Volt = 0x1,
    /// A.
    ///
    /// Reserved: allocated, and not specified yet.
    Ampere = 0x2,
    /// W.
    ///
    /// Reserved: allocated, and not specified yet.
    Watt = 0x3,
    /// Wh.
    ///
    /// Reserved: allocated, and not specified yet.
    WattHour = 0x4,
    /// Ah.
    ///
    /// Reserved: allocated, and not specified yet.
    AmpereHour = 0x5,
    /// °C.
    ///
    /// Reserved: allocated, and not specified yet.
    DegreeCelsius = 0x6,
    /// %.
    ///
    /// Reserved: allocated, and not specified yet.
    Percent = 0x7,
    /// Hz.
    ///
    /// Reserved: allocated, and not specified yet.
    Hertz = 0x8,
    /// s.
    ///
    /// Reserved: allocated, and not specified yet.
    Second = 0x9,
    /// min.
    ///
    /// Reserved: allocated, and not specified yet.
    Minute = 0xa,
    /// h.
    ///
    /// Reserved: allocated, and not specified yet.
    Hour = 0xb,
    /// a plain tally.
    ///
    /// Reserved: allocated, and not specified yet.
    Count = 0xc,
    /// Ω.
    ///
    /// Reserved: allocated, and not specified yet.
    Ohm = 0xd,
    /// Pa.
    ///
    /// Reserved: allocated, and not specified yet.
    Pascal = 0xe,
    /// L.
    ///
    /// Reserved: allocated, and not specified yet.
    Litre = 0xf,
    /// a number with no unit — an enum or a flags word.
    ///
    /// Reserved: allocated, and not specified yet.
    None = 0x10,
}

impl TryFrom<u8> for Unit {
    type Error = ();

    fn try_from(v: u8) -> Result<Self, Self::Error> {
        match v {
            0x1 => Ok(Self::Volt),
            0x2 => Ok(Self::Ampere),
            0x3 => Ok(Self::Watt),
            0x4 => Ok(Self::WattHour),
            0x5 => Ok(Self::AmpereHour),
            0x6 => Ok(Self::DegreeCelsius),
            0x7 => Ok(Self::Percent),
            0x8 => Ok(Self::Hertz),
            0x9 => Ok(Self::Second),
            0xa => Ok(Self::Minute),
            0xb => Ok(Self::Hour),
            0xc => Ok(Self::Count),
            0xd => Ok(Self::Ohm),
            0xe => Ok(Self::Pascal),
            0xf => Ok(Self::Litre),
            0x10 => Ok(Self::None),
            _ => Err(()),
        }
    }
}

/// Whether a number is usable now. Separated from provenance because `counted`
/// **and** `stale` is a real state and one word could not say it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
#[repr(u8)]
pub enum Validity {
    /// Current.
    Ok = 0x1,
    /// Was good; the value is the last known and `age` says how old.
    Stale = 0x2,
    /// The source is up and has not produced a first reading.
    Initialising = 0x3,
    /// This device does not implement it, including a vendor's in-band absence
    /// pattern (P-176).
    Unsupported = 0x4,
    /// The source reports it bad, or the reply did not arrive intact.
    SensorFault = 0x5,
    /// A number arrived and was refused: impossible here, or outside `i32` at
    /// the registry's scale (P-185).
    OutOfRange = 0x6,
    /// The component or device is not present.
    Absent = 0x7,
    /// The source reported an operating state we have no value for (P-164).
    UnnamedState = 0x8,
}

impl TryFrom<u8> for Validity {
    type Error = ();

    fn try_from(v: u8) -> Result<Self, Self::Error> {
        match v {
            0x1 => Ok(Self::Ok),
            0x2 => Ok(Self::Stale),
            0x3 => Ok(Self::Initialising),
            0x4 => Ok(Self::Unsupported),
            0x5 => Ok(Self::SensorFault),
            0x6 => Ok(Self::OutOfRange),
            0x7 => Ok(Self::Absent),
            0x8 => Ok(Self::UnnamedState),
            _ => Err(()),
        }
    }
}

/// What a single value is, independent of how many there are. Splitting this
/// from the shape is what lets a series of flags exist: sixteen per-cell
/// balancing bits are one signal, not sixteen.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
#[repr(u8)]
pub enum Vtype {
    /// A quantity that moves in both directions.
    ///
    /// Reserved: allocated, and not specified yet.
    Gauge = 0x1,
    /// A running total. It never reverses, which is why a coarse history bucket
    /// takes the last constituent and not their sum (P-195).
    ///
    /// Reserved: allocated, and not specified yet.
    Counter = 0x2,
    /// One member of the space named by `esp`.
    ///
    /// Reserved: allocated, and not specified yet.
    Enum = 0x3,
    /// A bitmask over the space named by `esp`; member m is bit m − 1 (P-186).
    ///
    /// Reserved: allocated, and not specified yet.
    Flags = 0x4,
}

impl TryFrom<u8> for Vtype {
    type Error = ();

    fn try_from(v: u8) -> Result<Self, Self::Error> {
        match v {
            0x1 => Ok(Self::Gauge),
            0x2 => Ok(Self::Counter),
            0x3 => Ok(Self::Enum),
            0x4 => Ok(Self::Flags),
            _ => Err(()),
        }
    }
}

