/// Whether a receiver may read this code out of a **bare** body.
///
/// The registry's sealed column, which is the receiver's check and never
/// the sender's: P-142 decides the shape by whether the *sender* holds
/// a session, so a rule read off this column would be one the cases
/// with no session cannot obey. What it says is what a receiver will
/// accept, and a bare body carrying a code marked here is discarded
/// under P-051 rather than acted on. Sorted, so a lookup can bisect.
pub const ERROR_NEEDS_A_SEAL: &[(u16, bool)] = &[
    (1, false),
    (2, false),
    (3, false),
    (4, false),
    (5, false),
    (6, true),
    (7, true),
    (8, false),
    (9, false),
    (10, false),
    (12, false),
    (14, false),
    (18, false),
    (19, false),
    (20, true),
];

impl ErrorCode {
    /// Whether a receiver refuses to read this code out of a bare body.
    #[must_use]
    pub fn needs_a_seal(self) -> bool {
        ERROR_NEEDS_A_SEAL
            .binary_search_by_key(&(self as u16), |&(c, _)| c)
            .ok()
            .and_then(|i| ERROR_NEEDS_A_SEAL.get(i))
            .is_some_and(|&(_, m)| m)
    }
}

/// Which records survive a controller under pressure.
///
/// The registry's class column, and the two words are defined there
/// normatively rather than in a design document — a column with no
/// definition beside it is one every implementation fills in for itself,
/// and the two answers it picks between are *keep this alarm* and *drop
/// it*. A controller that ranks a value change above an alarm raised
/// loses the alarm on the busiest day, which is the day it mattered.
/// Sorted, so a lookup can bisect.
pub const EVENT_IS_CLASS_A: &[(u16, bool)] = &[
    (258, true),
    (513, true),
    (514, true),
    (515, true),
    (769, true),
    (770, true),
    (1025, true),
    (1281, true),
    (1282, true),
    (1537, true),
    (1538, true),
    (1539, true),
    (1540, true),
    (1541, true),
    (1542, true),
    (1793, true),
    (1794, true),
    (2049, true),
    (2050, true),
    (2051, true),
    (2052, true),
    (2053, true),
    (2054, true),
    (2305, true),
    (2306, true),
];

impl EventKind {
    /// Whether this record is never dropped — not from the log, and not
    /// from a queue.
    ///
    /// `None` for a kind this build has never heard of. Not `false`: a
    /// controller that treated an unknown record as droppable would shed
    /// exactly the records a newer firmware added because they mattered.
    #[must_use]
    pub fn is_class_a(self) -> Option<bool> {
        EVENT_IS_CLASS_A
            .binary_search_by_key(&self.0, |&(k, _)| k)
            .ok()
            .and_then(|i| EVENT_IS_CLASS_A.get(i))
            .map(|&(_, a)| a)
    }
}

/// Errors on the link between the controller and its comms processor, numbered
/// from 256 so a client can tell *the link failed* from *your request failed*.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
#[repr(u16)]
pub enum LinkErrorCode {
    /// Unknown link-local opcode, or one sent from the wrong side. It never
    /// appears in a client-facing frame (L-180).
    WrongSide = 0x100,
    /// Link-local type on a client transport. It reaches the client whose frame
    /// raised it (L-180).
    LinkTypeOnClientTransport = 0x101,
    /// Client frame before `LinkUp` completed. It reaches the client whose
    /// frame raised it (L-180).
    BeforeLinkUp = 0x102,
    /// Unknown connection handle. It reaches the client whose frame raised it
    /// (L-180).
    UnknownHandle = 0x103,
    /// Connection table full. It never appears in a client-facing frame
    /// (L-180).
    ConnectionTableFull = 0x104,
    /// Link protocol major mismatch. It never appears in a client-facing frame
    /// (L-180).
    LinkMajorMismatch = 0x105,
    /// Too many outstanding link-local requests. It never appears in a
    /// client-facing frame (L-180).
    TooManyOutstanding = 0x106,
    /// Link-local type with a non-zero session. It never appears in a
    /// client-facing frame (L-180).
    NonZeroSession = 0x107,
    /// No authorisation matches this image. It never appears in a client-facing
    /// frame (L-180).
    NoAuthorisation = 0x108,
}

impl TryFrom<u16> for LinkErrorCode {
    type Error = ();

    fn try_from(v: u16) -> Result<Self, Self::Error> {
        match v {
            0x100 => Ok(Self::WrongSide),
            0x101 => Ok(Self::LinkTypeOnClientTransport),
            0x102 => Ok(Self::BeforeLinkUp),
            0x103 => Ok(Self::UnknownHandle),
            0x104 => Ok(Self::ConnectionTableFull),
            0x105 => Ok(Self::LinkMajorMismatch),
            0x106 => Ok(Self::TooManyOutstanding),
            0x107 => Ok(Self::NonZeroSession),
            0x108 => Ok(Self::NoAuthorisation),
            _ => Err(()),
        }
    }
}

/// A code off the wire, kept in the space it came from.
///
/// Widening `ErrorCode` to hold the link-local range would make a
/// routing fault in the comms processor look like the client's own
/// request failing, and the two want different retries.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
pub enum Incoming {
    /// A code from the client-facing space.
    Client(ErrorCode),
    /// A code from the link-local space.
    LinkLocal(LinkErrorCode),
    /// A code this build allocates in neither space, carried as sent.
    Unknown(u16),
}

impl From<u16> for Incoming {
    fn from(v: u16) -> Self {
        ErrorCode::try_from(v).map_or_else(
            |()| LinkErrorCode::try_from(v).map_or(Self::Unknown(v), Self::LinkLocal),
            Self::Client,
        )
    }
}

/// A per-client bitfield, the one the slot's role is handed. **P-105 in
/// [PROTOCOL.md](https://github.com/origin89hq/km43/blob/main/docs/PROTOCOL.md)
/// is the rule** — why the role decides and `client_kind` and `transport` do
/// not, that no message raises or lowers a mask, and what each refusal is
/// answered with. This file allocates the bits and the row each role is handed.
///
/// Not a wire discriminant: an unallocated bit is a capability nobody has
/// defined yet, not a value to reject.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
pub struct ClientCapability(pub u16);

impl ClientCapability {
    /// The client may write configuration at all.
    pub const WRITE_CONFIG: Self = Self(1 << 0);
    /// The client may write the **network** (`0x0020`) and **cloud** (`0x0021`)
    /// sections, and refresh a `WifiScan`.
    pub const WRITE_NETWORK_AND_CLOUD: Self = Self(1 << 1);
    /// The client may send `Command 0x08`.
    pub const SEND_COMMAND: Self = Self(1 << 2);
    /// The client may set the clock with `Time 0x0A`.
    pub const SET_CLOCK: Self = Self(1 << 3);
    /// The client may push firmware with `Firmware 0x09`.
    pub const PUSH_FIRMWARE: Self = Self(1 << 4);
    /// The client may read the **network** (`0x0020`) and **cloud** (`0x0021`)
    /// sections with `GetConfig`, the scan list with `WifiScan`, and the client
    /// table with `Clients 0x18`.
    pub const READ_PRIVATE: Self = Self(1 << 5);
    /// The client may propose an admin with `Invite 0x15`, and remove an admin
    /// with `Remove 0x17`.
    pub const INVITE: Self = Self(1 << 6);
    /// The client may approve or decline any invite with `Approve 0x16`,
    /// propose an owner or a viewer, and remove a viewer.
    pub const APPROVE: Self = Self(1 << 7);

    /// Whether this mask holds every bit of `want`.
    #[must_use]
    pub fn allows(self, want: Self) -> bool {
        self.0 & want.0 == want.0
    }

    /// The mask this role is handed.
    ///
    /// A slot's mask is its role's and nothing else: no message
    /// raises one and no message lowers one.
    ///
    /// Left unformatted: a kind list long enough to wrap would be
    /// rewritten by `cargo fmt` into something this generator does not
    /// emit, after which `cargo fmt` and `cargo xtask check` cannot
    /// both be green and the fix is not obvious from either.
    #[rustfmt::skip]
    #[must_use]
    pub const fn granted(role: Role) -> Self {
        match role {
            Role::Owner => Self(0b1111_1111),
            Role::Admin => Self(0b0111_1101),
            Role::Viewer => Self(0b0000_0000),
        }
    }
}

