/// What every enum space contains, by the registry's own tables. Sorted on
/// both axes, so a lookup can bisect. A space with no members is absent here
/// rather than present and empty.
pub const ENUM_SPACE_MEMBERS: &[(u16, &[i32])] = &[
    (0x0001, &[1, 2, 3, 4]),
    (0x0002, &[1, 2, 3, 4, 5, 6]),
    (0x0003, &[1, 2, 3, 4, 5, 6]),
    (0x0004, &[1, 2, 3]),
    (0x0005, &[1, 2, 4, 5, 6, 7, 8, 9]),
];

impl EnumSpace {
    /// The values this build can name in this space, or `None` where it names
    /// none at all.
    ///
    /// The `None` is the case worth having: a space allocated with no members
    /// can never name one of its own values, so a signal drawn from it reads
    /// `unnamed_state` at every poll. That is a registry entry half written,
    /// and it is a different thing from a device reporting a state this build
    /// has not heard of.
    #[must_use]
    pub fn members(self) -> Option<&'static [i32]> {
        let at = ENUM_SPACE_MEMBERS
            .binary_search_by_key(&self.0, |&(space, _)| space)
            .ok()?;
        ENUM_SPACE_MEMBERS.get(at).map(|&(_, members)| members)
    }

    /// Whether this build can name `value` as a member of this space.
    ///
    /// False for a space that names nothing, which is deliberate: the caller
    /// that needs to tell the two apart asks [`Self::members`].
    #[must_use]
    pub fn names(self, value: i32) -> bool {
        self.members()
            .is_some_and(|members| members.binary_search(&value).is_ok())
    }
}

/// Every metric with the unit and scale it is read in:
/// `value = raw * 10^scale`. Sorted, so a lookup can bisect.
pub const METRIC_UNITS: &[(u16, &str, i8)] = &[
    (0x0101, "V", -3),
    (0x0102, "A", -3),
    (0x0103, "W", -1),
    (0x0104, "%", -1),
    (0x0105, "°C", -1),
    (0x0110, "V", -3),
    (0x0111, "A", -3),
    (0x0112, "W", -1),
    (0x0120, "A", -3),
    (0x0121, "W", -1),
    (0x0130, "V", -3),
    (0x0201, "V", -1),
    (0x0202, "A", -3),
    (0x0203, "W", -1),
    (0x0204, "Hz", -2),
    (0x0205, "Wh", 0),
    (0x0206, "Wh", 0),
    (0x0207, "Wh", 0),
    (0x0301, "°C", -1),
    (0x0302, "°C", -1),
    (0x0401, "%", -1),
    (0x0402, "A", -6),
    (0x0501, "—", 0),
    (0x0502, "h", -2),
    (0x0503, "count", 0),
    (0x0504, "—", 0),
    (0x0601, "—", 0),
    (0x0602, "s", 0),
    (0x0603, "—", 0),
    (0x0604, "%", -1),
    (0x0701, "min", 0),
    (0x0702, "min", 0),
    (0x0703, "min", 0),
];

impl MetricKind {
    /// The unit and scale this kind is read in, or `None` for a kind this
    /// build has never heard of. Not a guess: a reading scaled by the wrong
    /// power of ten looks like a real one.
    #[must_use]
    pub fn unit_and_scale(self) -> Option<(&'static str, i8)> {
        METRIC_UNITS
            .binary_search_by_key(&self.0, |&(k, _, _)| k)
            .ok()
            .and_then(|i| METRIC_UNITS.get(i))
            .map(|&(_, u, s)| (u, s))
    }
}

